insert into public.sections (id, name, description, icon, subsections, sort_order, active) values ('school-news', 'School News', 'What''s happening at Avon High School — policies, programs, clubs and the Avon community.', 'school', array['Administration & Policy', 'Clubs & Activities', 'Academics', 'Avon & Community']::text[], 10, true) on conflict (id) do nothing;
insert into public.sections (id, name, description, icon, subsections, sort_order, active) values ('sports', 'Sports', 'Scores, recaps and athlete spotlights for every Falcon team.', 'trophy', array['Fall', 'Winter', 'Spring', 'Athlete Spotlights']::text[], 20, true) on conflict (id) do nothing;
insert into public.sections (id, name, description, icon, subsections, sort_order, active) values ('opinion-advice', 'Opinion + Advice', 'Editorials, student voices, letters to the editor and advice you can actually use.', 'pen', array['Staff Editorials', 'Student Voices', 'Letters to the Editor', 'Advice']::text[], 30, true) on conflict (id) do nothing;
insert into public.sections (id, name, description, icon, subsections, sort_order, active) values ('culture-entertainment', 'Culture + Entertainment', 'Music, film, books, games, performances and everything students are into right now.', 'masks', array['Music', 'Film & TV', 'Books & Games', 'Arts & Performances']::text[], 40, true) on conflict (id) do nothing;
insert into public.sections (id, name, description, icon, subsections, sort_order, active) values ('social-media', 'Social Media', 'Highlights from our social channels, behind-the-scenes looks and what''s trending in the halls.', 'phone', array['Highlights', 'Behind the Scenes', 'Trending']::text[], 50, true) on conflict (id) do nothing;
insert into public.sections (id, name, description, icon, subsections, sort_order, active) values ('photo-video', 'Photography + Video', 'Photo essays, event galleries and video from around campus.', 'camera', array['Photo Essays', 'Event Galleries', 'Video']::text[], 60, true) on conflict (id) do nothing;
