insert into public.articles (slug, title, deck, body_md, section_id, subsection, status, is_lead, published_at, tags) values ('welcome-to-the-falcon-times', 'Welcome to the new Falcon Times', 'Avon High School’s student newspaper has a new home, a new team, and a way for every student to be heard.', 'The Falcon Times is the student newspaper of Avon High School, written, photographed, designed and published by the Avon High School Newspaper Club. This is the first issue of our new home on the web, and we''re glad you''re here.
